// Install: npm install react react-dom styled-components @carbon/react
import React from 'react';
import ReactDOM from 'react-dom';
import styled from 'styled-components';
import { Theme } from '@carbon/react';

// Container that uses the CSS custom properties applied by the Theme component
const InverseContainer = styled.div`
  background-color: var(--cds-inverse-01);
  padding: 2rem;
  color: var(--cds-text-inverse);
`;

// Link styled to pick up the new inverse‐hover and inverse‐active tokens
const InverseLink = styled.a`
  color: var(--cds-link-inverse);
  text-decoration: underline;
  &:hover {
    color: var(--cds-link-hover-inverse);
  }
  &:active {
    color: var(--cds-link-inverse-active);
  }
`;

function Example({ theme }) {
  return (
    <Theme theme={theme}>
      <InverseContainer>
        <p>
          Lorem ipsum dolor sit amet, consectetur adipiscing elit.{' '}
          <InverseLink href="#">Learn more</InverseLink>
        </p>
      </InverseContainer>
    </Theme>
  );
}

function App() {
  return (
    <>
      {/* Light inverse (g10) */}
      <Example theme="g10" />
      {/* Dark inverse (g100) */}
      <Example theme="g100" />
    </>
  );
}

ReactDOM.render(<App />, document.getElementById('root'));
